"""Original questions on cytotoxic and molecular treatment principles."""
from qbank_authoring import question,ref
rows=[]
def q(*args,**kwargs):rows.append(question(*args,**kwargs))
def drug(name):return ref('NCI drug dictionary: '+name,'https://www.cancer.gov/publications/dictionaries/cancer-drug/def/'+name)
TG=ref('NCI targeted cancer therapy overview','https://www.cancer.gov/about-cancer/treatment/types/targeted-therapies')

q('Which mechanism best characterizes cisplatin antitumor activity?', 'Formation of platinum–DNA adducts and cross-links that disrupt replication and transcription',[
 ('Inhibition of microtubule depolymerization','This is characteristic of taxanes.'),('Selective inhibition of dihydrofolate reductase','This is the principal folate-pathway target of methotrexate.'),('Estrogen-receptor degradation','This is an endocrine mechanism, not platinum action.')],
 'DNA damage rather than receptor blockade','**Platinum compounds create structurally disruptive DNA lesions.**',['Repair capacity influences cellular sensitivity.','Their classification and adverse-effect profile differ from other DNA-damaging drugs.'],'**Select the platinum and dose according to the disease and organ function.**',['Cisplatin and carboplatin are not automatically dose-interchangeable.','Renal, neurological, hearing and marrow risks affect selection.'],[['Platinum','DNA adducts/cross-links'],['Taxane','Microtubule stabilization'],['Methotrexate','Folate-pathway inhibition']],[drug('cisplatin')])

q('A fluorouracil metabolite forms an inhibitory complex with thymidylate synthase. Which immediate biochemical consequence contributes to cytotoxicity?', 'Reduced synthesis of thymidylate needed for DNA synthesis',[
 ('Enhanced microtubule assembly','Fluorouracil is not a tubulin-targeting drug.'),('Direct blockade of the androgen receptor','This is an endocrine-treatment mechanism.'),('Selective inhibition of BCR::ABL kinase','That is a molecular kinase target, unrelated to thymidylate synthesis.')],
 'An antimetabolite interferes with nucleotide metabolism','**FdUMP inhibits thymidylate synthase in a folate-dependent complex.**',['Other fluorouracil metabolites can also disrupt RNA and DNA.','Schedule influences exposure and toxicity.'],'**Recognize that leucovorin can enhance this fluorouracil effect.**',['This differs from its rescue role after high-dose methotrexate.','Pretreatment DPD assessment and protocol-specific dosing remain important.'],[['FdUMP','Thymidylate synthase'],['DNA effect','Thymidylate depletion'],['Leucovorin here','Biochemical modulation']],[drug('fluorouracil')])

q('Why is leucovorin used after appropriately timed high-dose methotrexate?', 'It supplies reduced folate to rescue normal cells from folate-pathway blockade',[
 ('It increases methotrexate binding to tubulin','Methotrexate is not a tubulin poison.'),('It directly converts methotrexate into an inactive metabolite in plasma','Glucarpidase, not leucovorin, enzymatically cleaves circulating methotrexate.'),('It prevents renal injury by replacing hydration and urine alkalinization','Rescue does not replace clearance-support measures and monitoring.')],
 'Rescue and drug elimination are complementary','**Methotrexate inhibits dihydrofolate reductase and disrupts reduced-folate metabolism.**',['Leucovorin timing and dose follow the treatment protocol and drug levels.','Delayed clearance requires rapid specialist adjustment.'],'**Continue concentration-guided rescue with appropriate renal monitoring.**',['Ensure hydration and urine alkalinization as indicated.','Assess glucarpidase eligibility in toxic delayed elimination with renal dysfunction.'],[['Leucovorin','Reduced-folate rescue'],['Support','Hydration/alkalinization'],['Glucarpidase','Enzymatic drug cleavage']],[drug('methotrexate'),drug('leucovorin-calcium')])

q('Which pairing correctly distinguishes paclitaxel from vincristine?', 'Paclitaxel stabilizes microtubules; vincristine inhibits their assembly',[
 ('Both selectively inhibit topoisomerase I','Neither is classified by that mechanism.'),('Paclitaxel inhibits assembly while vincristine stabilizes formed microtubules','This reverses their characteristic actions.'),('Both act principally through estrogen-receptor blockade','Their antimitotic action is unrelated to estrogen-receptor antagonism.')],
 'Opposite effects can both disrupt spindle dynamics','**Successful mitosis requires dynamic microtubule assembly and disassembly.**',['Taxanes and vinca alkaloids interrupt different parts of that process.','They have distinct dose-limiting toxicities and administration precautions.'],'**Do not infer interchangeability from a shared antimitotic label.**',['Assess neuropathy risk.','Vincristine must never be administered intrathecally.'],[['Taxane','Stabilization'],['Vinca alkaloid','Assembly inhibition'],['Shared consequence','Disrupted mitotic spindle']],[drug('paclitaxel'),drug('vincristine-sulfate')])

q('Which drug–target pairing is correct?', 'Irinotecan/SN-38 — topoisomerase I',[
 ('Etoposide — topoisomerase I','Etoposide targets topoisomerase II.'),('Vincristine — thymidylate synthase','Vincristine disrupts microtubule assembly.'),('Methotrexate — topoisomerase II','Methotrexate inhibits folate metabolism.')],
 'Topoisomerase poisons interfere with DNA strand handling','**SN-38 is the active metabolite of irinotecan.**',['Topoisomerase I normally creates transient single-strand breaks.','Etoposide interferes with topoisomerase II-mediated DNA handling.'],'**Separate target knowledge from toxicity and pharmacokinetics.**',['UGT1A1-mediated glucuronidation affects SN-38 exposure.','Diarrhea and neutropenia are important irinotecan risks.'],[['Irinotecan','Topoisomerase I'],['Etoposide','Topoisomerase II'],['Vincristine','Tubulin']],[drug('irinotecan-hydrochloride'),drug('etoposide')])

q('Which mechanism contributes to doxorubicin activity?', 'DNA intercalation and topoisomerase II interference, with free-radical generation',[
 ('Selective inhibition of aromatase','That is an endocrine mechanism.'),('Blockade of the extracellular PD-1 checkpoint','That describes an immunotherapy target.'),('Direct depletion of circulating asparagine as its principal action','That is characteristic of asparaginase.')],
 'Anthracyclines have multiple interacting cellular effects','**DNA damage and oxidative injury contribute to anthracycline effects.**',['Cumulative exposure is relevant to cardiac risk.','Formulation, previous therapy and cardiovascular factors modify risk.'],'**Plan baseline risk assessment and treatment-specific surveillance.**',['Account for prior anthracycline exposure.','Consider protective or alternative strategies in appropriate patients.'],[['DNA','Intercalation/topoisomerase II'],['Oxidative stress','Contributes to injury'],['Clinical concern','Cumulative cardiotoxicity']],[drug('doxorubicin-hydrochloride')])

q('Which process is most closely associated with bleomycin cytotoxicity?', 'Free-radical-mediated DNA strand damage',[
 ('Proteasome inhibition','That is characteristic of agents such as bortezomib.'),('Estrogen synthesis inhibition','That is the aromatase-inhibitor pathway.'),('Selective CD20-positive B-cell depletion','That describes an anti-CD20 antibody effect.')],
 'A DNA-damaging drug with a distinctive organ risk','**Bleomycin causes DNA strand injury through metal- and oxygen-dependent chemistry.**',['It is used in selected curative regimens.','Pulmonary toxicity is an important treatment-limiting complication.'],'**Evaluate new respiratory symptoms promptly.**',['Integrate cumulative exposure, renal function and other risk factors.','Provide necessary oxygen in hypoxemia while avoiding unnecessary hyperoxia.'],[['Mechanism','DNA strand damage'],['Major concern','Pulmonary toxicity'],['Clinical response','Prompt respiratory assessment']],[drug('bleomycin-sulfate')])

q('Which principle best explains combining cytotoxic drugs in a validated regimen?', 'Complementary activity and resistance patterns may improve tumor control, while overlapping toxicity constrains the combination',[
 ('Any two active drugs necessarily produce superior survival together','Combinations require evidence and may worsen toxicity without benefit.'),('Using drugs with identical limiting toxicities always permits higher doses','Overlapping toxicity can reduce deliverable treatment.'),('Activity of one component makes dose, sequence and schedule irrelevant','Regimen efficacy and safety depend on those features.')],
 'A regimen is an evidence-based system','**Combination benefit cannot be assumed from the activity of individual drugs.**',['Mechanism, resistance and normal-tissue toxicity all matter.','Dose and schedule are integral to the studied treatment.'],'**Use disease- and intent-specific protocols.**',['Assess organ function, interactions and supportive needs.','Modify safely when toxicity or patient circumstances require it.'],[['Potential benefit','Complementary tumor activity'],['Constraint','Overlapping toxicity'],['Evidence','Regimen-specific outcomes']],[ref('NCI chemotherapy overview','https://www.cancer.gov/about-cancer/treatment/types/chemotherapy')])

q('A metastatic GIST contains a PDGFRA D842V alteration. Which targeted agent has specific activity and an established indication in this molecular setting?', 'Avapritinib',[
 ('Imatinib selected because every PDGFRA mutation has identical sensitivity','D842V is a recognized imatinib-resistant alteration.'),('Cetuximab','EGFR antibody therapy is not the matched treatment for this GIST alteration.'),('Trastuzumab','HER2-directed therapy does not match PDGFRA D842V.')],
 'The exact variant matters, not merely the gene name','**PDGFRA D842V changes drug sensitivity within GIST.**',['Mutation-directed selection can avoid an ineffective default agent.','Fitness, interactions and drug-specific adverse effects still need review.'],'**Use a specialist molecularly matched treatment pathway.**',['Confirm the reported variant and treatment setting.','Monitor cognition, bleeding risk and other label-defined toxicities.'],[['Alteration','PDGFRA D842V'],['Matched agent','Avapritinib'],['Common trap','Assuming universal imatinib sensitivity']],[ref('FDA avapritinib prescribing information 2026','https://www.accessdata.fda.gov/drugsatfda_docs/label/2026/212035s004lbl.pdf')],style='clinical_scenario')

q('Why does an activating RAS mutation generally predict lack of benefit from standard cetuximab or panitumumab therapy in metastatic colorectal cancer?', 'Constitutive downstream signaling can bypass inhibition of the upstream EGFR receptor',[
 ('RAS mutations prevent all cytotoxic drugs from entering the cell','This is not the basis of anti-EGFR resistance.'),('RAS is the extracellular antigen directly bound by cetuximab','Cetuximab binds EGFR, not intracellular RAS.'),('Any RAS mutation establishes MSI-high disease','RAS and mismatch-repair status are distinct biomarkers.')],
 'An active downstream pathway can evade upstream blockade','**Expanded RAS testing is central to conventional anti-EGFR selection.**',['Primary-sidedness, other biomarkers and treatment line also matter.','Specific approved KRAS-targeted combinations are a separate context.'],'**Interpret the complete molecular and clinical setting.**',['Do not generalize this rule to every targeted combination.','Confirm adequate assay coverage.'],[['EGFR','Upstream receptor'],['RAS activation','Downstream signaling'],['Selection','Biomarker and disease context']],[ref('NCI colon cancer professional summary','https://www.cancer.gov/types/colorectal/hp/colon-treatment-pdq')])

q('Which description best characterizes an antibody–drug conjugate?', 'An antibody linked to a cytotoxic payload, designed to deliver the payload through target-associated binding and processing',[
 ('Two antibodies joined together with no cytotoxic component','That is not the defining ADC structure.'),('A small molecule that blocks all receptor kinases equally','That describes neither its structure nor its selectivity.'),('A vaccine that must induce lifelong immunity before having activity','ADCs do not depend on that mechanism.')],
 'Target recognition and payload action are different components','**An ADC combines an antibody, linker and payload.**',['Target expression, internalization and payload properties influence activity.','Bystander effects vary with the particular conjugate.'],'**Use the indication-specific biomarker definition.**',['Do not assume every antibody against the same antigen is interchangeable.','Recognize payload-related and target-associated toxicities.'],[['Antibody','Target recognition'],['Linker','Payload attachment/release'],['Payload','Cytotoxic action']],[TG])

q('Why can a BRCA-deficient tumor be particularly susceptible to a PARP inhibitor?', 'Combined impairment of complementary DNA-repair processes can produce synthetic lethality',[
 ('PARP inhibition restores the missing BRCA protein','It exploits rather than repairs the underlying defect.'),('BRCA status identifies an estrogen receptor on the cell surface','BRCA genes primarily relate to DNA repair, not receptor expression.'),('PARP inhibitors act only by suppressing ovarian estrogen synthesis','They are DNA-repair-directed agents.')],
 'A pre-existing repair weakness becomes a therapeutic vulnerability','**Homologous-recombination defects can increase dependence on alternative repair pathways.**',['PARP trapping and repair interference contribute to activity.','Eligibility differs by tumor, biomarker, prior therapy and current indication.'],'**Confirm the relevant validated biomarker and disease setting.**',['Resistance can develop, including restoration of repair capability.','Monitor blood counts and other agent-specific adverse effects.'],[['BRCA function','Homologous recombination'],['PARP inhibition','Repair stress/trapping'],['Interaction','Synthetic lethality']],[ref('NCI drug dictionary: olaparib','https://www.cancer.gov/publications/dictionaries/cancer-drug/def/olaparib')])

q('What is the main cell-cycle effect of CDK4/6 inhibition in an appropriate hormone-receptor-positive breast cancer?', 'Reduced retinoblastoma-protein phosphorylation and restriction of G1-to-S progression',[
 ('Direct inhibition of microtubule depolymerization during mitosis','That is a taxane-type mechanism.'),('Enzymatic destruction of circulating estrogen','That is not the CDK4/6 mechanism.'),('Covalent cross-linking of DNA as a platinum analogue','CDK4/6 inhibitors are cell-cycle kinase inhibitors.')],
 'The cell-cycle checkpoint complements endocrine therapy','**Cyclin D–CDK4/6 signaling promotes passage through the G1 restriction point.**',['An intact relevant downstream pathway is important to the mechanism.','These agents are used in defined breast-cancer settings, often with endocrine therapy.'],'**Choose the agent and schedule using the disease setting and comorbidities.**',['Neutropenia, diarrhea and QT effects differ across the class.','Review interactions and monitoring requirements.'],[['Target','CDK4/6'],['Downstream','Retinoblastoma pathway'],['Transition','G1 to S']],[drug('palbociclib')])

q('A lung adenocarcinoma has a validated ALK rearrangement. Which treatment principle follows?', 'Use an ALK-directed strategy appropriate to stage and treatment setting rather than treating ALK as a nonspecific prognostic stain',[
 ('Treat the rearrangement as equivalent to KRAS activation','These are different oncogenic drivers with different matched drugs.'),('Choose endocrine therapy because ALK is an estrogen receptor','ALK is a receptor tyrosine kinase, not an estrogen receptor.'),('Use PD-L1 expression as the sole determinant while disregarding the driver','An actionable driver can substantially alter treatment selection.')],
 'A predictive driver can determine the treatment pathway','**ALK rearrangements create oncogenic kinase signaling.**',['CNS activity and resistance mechanisms influence agent choice.','A validated test and stage-specific evidence are required.'],'**Plan therapy with thoracic oncology and appropriate molecular review.**',['Avoid assuming all kinase inhibitors cover ALK.','Reassess mechanisms and options when resistance develops.'],[['Driver','ALK rearrangement'],['Treatment','ALK-directed strategy'],['Selection factors','Stage, CNS disease, prior therapy']],[ref('ASCO NSCLC driver-alteration living guideline 2026','https://doi.org/10.1200/JCO-26-01958')],style='clinical_scenario')

q('Which statement best distinguishes a prognostic from a predictive cancer biomarker?', 'A prognostic marker informs outcome, whereas a predictive marker informs relative benefit or resistance to a particular treatment',[
 ('A prognostic marker necessarily identifies the best drug','Outcome association does not automatically establish differential treatment benefit.'),('A predictive marker guarantees response in every positive patient','It changes expected benefit; response is not guaranteed.'),('A marker cannot have both prognostic and predictive roles','Some biomarkers have both roles in defined contexts.')],
 'The clinical question defines the role of the marker','**Association with outcome and interaction with treatment are different claims.**',['A marker may carry different implications in different tumor types.','Analytical validity does not by itself establish clinical utility.'],'**Use evidence matched to the treatment decision.**',['Check the assay, threshold and studied population.','Do not assume a biologically interesting alteration is actionable.'],[['Prognostic','Outcome information'],['Predictive','Treatment-benefit information'],['Actionability','Requires clinical evidence']],[TG])

q('Which mechanism most directly explains acquired resistance after an initially effective targeted therapy?', 'Selection or emergence of resistant clones through target alteration, bypass signaling or phenotypic change',[
 ('Initial response proves that subsequent progression cannot be cancer','Tumors evolve under selective pressure.'),('Every progressing lesion must have the same resistance mechanism','Resistance can be spatially heterogeneous.'),('Resistance always means the original biomarker was falsely positive','A genuine driver can remain while additional changes confer resistance.')],
 'A tumor is an evolving population','**Treatment pressure can select resistant subclones.**',['Secondary target mutations and alternative signaling are possible.','Histological transformation is relevant in selected diseases.'],'**Use rebiopsy or plasma testing when it can change treatment.**',['Consider distribution and pace of progression.','A negative plasma result may still require tissue evaluation.'],[['Target change','Reduced drug sensitivity'],['Bypass','Alternative signaling'],['Transformation','Changed tumor phenotype']],[TG])
